//! POC (Progression Order Change, marker 0xFF5F) decode regression test.
//!
//! POC lets the packet progression order change mid-codestream (ITU-T T.800 §B.12) — a feature
//! OpenJPH skips entirely (so it was absent from jph-rs and mis-decoded). The decoder must read
//! packets in the POC order and assign each to the right (component, resolution, layer, precinct);
//! getting the order wrong corrupts the image. These reversible fixtures therefore decode
//! bit-exact only when POC is honoured.
//!
//! Fixtures (regenerated by the dev harness; point `MLDIR` at the directory holding them):
//!   kdu_compress -i test.pgm -o poc_sl.j2c  Creversible=yes Clevels=3 Cmodes=HT Clayers=1 \
//!       Cprecincts="{32,32}" "Porder={0,0,1,2,1,RPCL},{2,0,1,4,1,PCRL}"
//!   kdu_compress ... poc1.j2c   Clayers=3 "Porder={0,0,1,4,1,LRCP},{0,0,3,4,1,RPCL}"
//!   kdu_compress ... poc_ml.j2c Clayers=3 Cprecincts="{32,32}" "Porder={0,0,1,4,1,LRCP},{0,0,3,4,1,RPCL}"
//!   kdu_compress ... poc_lay.j2c Clayers=4 "Porder={0,0,2,4,1,LRCP},{0,0,4,4,1,CPRL}"
//!   kdu_expand -i <f>.j2c -o <f>_ref.pgm   (== the original test.pgm, since reversible)
//! Passes trivially when `MLDIR` / a fixture is absent, so CI without it stays green.

use std::path::PathBuf;
mod common;

fn load_pgm(path: &PathBuf) -> Vec<i32> {
    common::pgm(path).2
}


#[test]
#[ignore = "needs external conformance fixtures (env vars): run with --ignored"]
fn poc_decode_matches_kakadu_bit_exact() {
    let Ok(dir) = std::env::var("MLDIR") else {
        panic!("MLDIR unset — skipping POC validation");
    };
    let dir = PathBuf::from(dir);
    let mut checked = 0;
    // poc_sl: single-layer (POC across resolutions, isolates POC from multi-layer);
    // poc1/poc_ml/poc_lay: POC composed with 3/3/4 quality layers.
    for stem in ["poc_sl", "poc1", "poc_ml", "poc_lay"] {
        let cs_path = dir.join(format!("{stem}.j2c"));
        let ref_path = dir.join(format!("{stem}_ref.pgm"));
        if !cs_path.exists() || !ref_path.exists() {
            continue;
        }
        let img = jph_rs::mem::decode(&std::fs::read(&cs_path).unwrap());
        let expected = load_pgm(&ref_path);
        let got = &img.planes[0].samples;
        assert_eq!(got.len(), expected.len(), "{stem}: sample count");
        // Reversible -> a correct POC decode is bit-exact against Kakadu.
        let ndiff = got.iter().zip(&expected).filter(|(a, b)| a != b).count();
        assert_eq!(ndiff, 0, "{stem}: {ndiff} samples differ (POC order mis-decoded?)");
        checked += 1;
        println!("{stem}: bit-exact ({} samples)", got.len());
    }
    if checked == 0 {
        eprintln!("no poc_*.j2c fixtures found — skipping");
    }
}
